const updateInit=Cloud.init.bind(Cloud);Cloud.init=async function(){if(!(await Store.get('meta','google-config')))await Store.put('meta',{k:'google-config',value:DEFAULT_GOOGLE});Schema.fields=(await Store.get('meta','capture-schema'))?.value||[];await updateInit();};
const functionsView=Portal.homeView.bind(Portal);
Portal.shell=function(body){return '<div class="v3-top"><div>'+vb('Indicadores','home')+vb('Funciones','functions')+' <span class="badge">'+esc(this.role==='admin'?'Administrador':this.role==='calidad'?'Calidad':'Instalaciones')+'</span> '+esc(this.person)+'</div>'+vb('Cerrar sesión','logout')+'</div>'+body;};
const Dash={filters:{},legacy:[],
 rows(){const m=new Map(Cloud.summaries.map(r=>[r.UUID,{id:r.UUID,kind:r.Actividad,system:r.Sistema,location:r.Ubicación,date:String(r.Fecha).slice(0,10),state:r.Estado,title:r.Consecutivo,central:true}]));for(const r of [...this.legacy,...Portal.records]){if(!Portal.can(r.kind==='FNC'||r.kind==='FHC'?'nc':r.kind))continue;const prev=m.get(r.id);if(!prev||!r._cloudVersion)m.set(r.id,{...r,title:r.code||r.title||'Borrador',central:!!prev});}return [...m.values()].filter(r=>r.state!=='Eliminado').map(r=>{let w;try{w=isoWeek(r.date);}catch{}return {...r,week:w?w.year+'-W'+String(w.week).padStart(2,'0'):'Sin fecha',month:r.date?.slice(0,7)||'Sin fecha'};});},
 view(){const all=this.rows(),dimensions=[['kind','Tipo de actividad'],['system','Sistema'],['location','Ubicación'],['week','Semana ISO'],['month','Mes']],rows=all.filter(r=>dimensions.every(([k])=>!this.filters[k]||r[k]===this.filters[k]));return Portal.shell('<section class="v3-hero"><div><img src="'+SA.logo+'" alt="SOFRATESA"><span class="v3-eyebrow">Gerencia de Calidad</span><h1>Indicadores</h1><p>Seguimiento de los registros de SOF-CAL</p></div>'+vb('Ir a Funciones →','functions','','pri')+'</section><section class="card"><div class="grid3">'+dimensions.map(([k,l])=>'<label class="fld"><span>'+l+'</span><select data-dashboard="'+k+'"><option value="">Todos</option>'+[...new Set(all.map(r=>r[k]).filter(Boolean))].sort().map(v=>'<option '+(this.filters[k]===v?'selected':'')+' value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'</select></label>').join('')+'</div>'+vb('Limpiar filtros','dashboard-clear')+vb('Actualizar','dashboard-refresh')+'<p id="google-state">'+esc(Cloud.error||'Incluye registros centrales consultados y borradores locales. Actualización central cada 30 segundos mientras la app está activa.')+'</p><div class="sf-metrics">'+[['Registros',rows.length],['Finalizados',rows.filter(r=>r.state==='Finalizada').length],['Borradores',rows.filter(r=>r.state==='Borrador').length]].map(([l,n])=>'<div class="sf-metric"><span>'+l+'</span><strong>'+n+'</strong></div>').join('')+'</div></section><div class="grid2">'+dimensions.map(([k,l])=>{const counts={};rows.forEach(r=>counts[r[k]||'Sin dato']=(counts[r[k]||'Sin dato']||0)+1);return '<section class="card"><h3>'+l+'</h3><div class="dashboard-bars">'+Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([v,n])=>'<button class="dash-bar" data-v3="dashboard-group" data-key="'+k+'" data-value="'+esc(v)+'"><span>'+esc(v)+'</span><b>'+n+'</b><i style="width:'+100*n/Math.max(1,rows.length)+'%"></i></button>').join('')+'</div></section>';}).join('')+'</div><section class="card"><h3>Registros · '+rows.length+'</h3>'+rows.map(r=>'<div class="v3-row"><div><b>'+esc(r.title)+'</b><p>'+esc([r.kind,r.system,r.location,r.date,r.state].filter(Boolean).join(' · '))+'</p></div>'+vb('Abrir',r.central?'google-download':r.legacy?'legacy-open':'open','data-id="'+esc(r.id)+'"')+'</div>').join('')+'</section>');},
 async load(){this.legacy=(await Insp.all()).map(i=>({id:i.uuid,kind:i.sis==='Materiales'?'materiales':'inspeccion',system:i.sis,location:i.datos?.ubicacion||i.datos?.zona||'',date:i.datos?.fecha,state:i.estado,title:i.consec,legacy:true,_cloudVersion:i._cloudVersion}));}
};
Portal.homeView=()=>Dash.view();
const homeBefore=Portal.home.bind(Portal);Portal.home=async function(){await Dash.load();await homeBefore();};
const updatedView=Portal.view.bind(Portal);Portal.view=function(){if(this.role&&this.page==='functions')return functionsView().replace('<h3>Administración</h3>','<h3>Administración</h3>'+vb('Campos y tipos de datos','schema-admin')+vb('Conexión Google','google-config'));return updatedView();};
const oldRecordList=Portal.recordList.bind(Portal);Portal.recordList=function(rs){return rs.map(r=>oldRecordList([r]).replace('</div></div>','</div></div>')).join('').replace(/(<button[^>]*data-v3="open"[^>]*data-id="([^"]+)"[^>]*>[\s\S]*?<\/button>)/g,(s,btn,id)=>{const r=rs.find(r=>r.id===id);return btn+(r?.state==='Borrador'&&(!r._cloudOwner||r._cloudOwner===Cloud.user?.email||Portal.role==='admin')?vb('Eliminar borrador','draft-delete','data-id="'+esc(id)+'"','danger-o'):'');});};
async function deleteDraft(id,legacy=false){if(Cloud.busy)throw Error('Espere a que termine la sincronización y vuelva a intentar.');await Portal.flush();const r=legacy?await Insp.get(id):Portal.records.find(x=>x.id===id);if(!r||(legacy?r.estado:r.state)!=='Borrador')throw Error('Solo se pueden eliminar borradores.');if(r._cloudOwner&&r._cloudOwner!==Cloud.user?.email&&Portal.role!=='admin')throw Error('Solo el autor o administrador puede eliminarlo.');if(!await UI.confirm('Eliminar borrador','Se quitará del historial. Los consecutivos utilizados no se reutilizarán. Los archivos ya emitidos se conservan.','Eliminar borrador'))return;
 clearTimeout(Cloud.timer);Cloud.busy=true;try{if(r._cloudVersion){if(!Cloud.user||!navigator.onLine)throw Error('Conéctese con Google para eliminar este borrador sincronizado.');await Cloud.api('deleteDraft',{id,baseVersion:r._cloudVersion});}await Store.put('meta',{k:'deleted-draft|'+id,at:nowISO()});for(const x of await Store.all('meta'))if(x.k==='v3-record|'+id||x.k==='v3-ack|'+id||x.k==='google-pending|'+id||x.k==='google-conflict|'+id||x.k.startsWith('google-file|'+id+'|'))await Store.del('meta',x.k);if(legacy){await Store.del('inspections',id);for(const p of await Photos.list(id))await Store.del('photos',p.id);}Portal.records=Portal.records.filter(x=>x.id!==id);Cloud.summaries=Cloud.summaries.filter(x=>x.UUID!==id);if(Portal.record?.id===id)Portal.record=null;if(App.insp?.uuid===id)App.insp=null;await Dash.load();Portal.page='history';App.view='portal';render();UI.toast('Borrador eliminado.','ok');}finally{Cloud.busy=false;}}
const linksView=DocLinks.view.bind(DocLinks);DocLinks.query='';DocLinks.project='';DocLinks.view=function(){const original=Portal.links;const q=norm(this.query);Portal.links=original.filter(l=>(!q||norm([l.title,l.notes,l.contractor,l.revision,l.project,l.url].join(' ')).includes(q))&&(!this.project||l.project===this.project));let html;try{html=linksView();}finally{Portal.links=original;}return html.replace('<h2>Documentación de consulta</h2>','<h2>Documentación de consulta</h2><div class="grid2"><label class="fld"><span>Buscar título, sistema, estación, código, revisión o contratista</span><input id="doc-query" value="'+esc(this.query)+'" placeholder="Ej.: ASC, E07, revisión V2…"></label><label class="fld"><span>Proyecto</span><select id="doc-project"><option value="">Todos</option>'+[...new Set(original.map(x=>x.project).filter(Boolean))].sort().map(v=>'<option '+(v===this.project?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label></div>'+vb('Buscar','doc-search')+vb('Limpiar filtros','doc-clear'));};
Portal.helpView=function(){return this.shell('<section class="card"><h2>Ayuda · SOF-CAL</h2><ol><li><b>Inicio — Indicadores:</b> filtra por actividad, sistema, ubicación, semana ISO y mes. Toca una barra para consultar sus registros. Actualizar incorpora datos centrales; los borradores locales también cuentan.</li><li><b>Funciones:</b> abre el menú para crear inspecciones, liberaciones, recepciones, protocolos, rayados, solicitudes, FNC/FHC y análisis de causa raíz según tu perfil.</li><li><b>Pestañas superiores:</b> Datos, Formato, Participantes y Revisión permanecen arriba. Desliza horizontalmente si no caben. Usa Continuar al final de cada paso.</li><li><b>Borradores:</b> en Historial pulsa Eliminar borrador. Solo el autor o administrador puede eliminarlo; los sincronizados requieren conexión. No se reutilizan consecutivos ni se borran documentos emitidos.</li><li><b>Documentación:</b> combina categoría, proyecto y búsqueda por título, sistema, estación, revisión o contratista. Las sensibilizaciones están en esta sección.</li><li><b>Campos y tipos de datos — administrador:</b> agrega campos por función o para todas; usa texto, texto largo, número, fecha o lista. Edita etiquetas y opciones. Desde una ficha usa Configurar campos de esta pantalla para adaptar campos existentes. Los identificadores, permisos y consecutivos son protegidos. Los datos adicionales se guardan y sincronizan; no se insertan automáticamente en los formatos controlados.</li><li><b>Google:</b> la dirección del servidor y de Sheets vienen preconfiguradas. El administrador puede cambiarlas desde Funciones. La carpeta destino de Drive se administra allí. Se requiere publicar la actualización del servidor incluida en el paquete.</li><li><b>Documentos controlados:</b> revisa todas las páginas antes de exportar. FNC/FHC se emiten como Word y sus firmas se completan fuera de la app. Las liberaciones conservan su política de firmas.</li><li><b>Respaldo:</b> exporta periódicamente los registros. Un dato guardado localmente no equivale a sincronizado: consulta el estado de Google y resuelve los pendientes.</li></ol></section>');};
const Schema={fields:[],
 current(){return App.view==='portal'?Portal.record:App.insp;},
 scope(r=this.current()){return r?.uuid?(r.sis==='MAT'?'materiales':'inspeccion'):r?.kind||'*';},
 applicable(r){return this.fields.filter(f=>f.active!==false&&(f.scope==='*'||f.scope===this.scope(r)));},
 input(f,value){const opts=f.options||[],v=value??'';if(f.type==='select')return '<select><option value="">— Seleccione —</option>'+[...new Set([...opts,...(v&&!opts.includes(String(v))?[String(v)]:[])])].map(x=>'<option '+(String(v)===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select>';if(f.type==='textarea')return '<textarea>'+esc(v)+'</textarea>';return '<input type="'+f.type+'" '+(f.type==='number'?'step="any" ':'')+'value="'+esc(v)+'">';},
 value(r,f){return f.binding?f.binding.split('.').reduce((o,k)=>o?.[k],r):r.customData?.[f.id];},
 async edit(id,preset={}){requireAdmin();const f=this.fields.find(x=>x.id===id)||{id:uuid(),scope:this.scope(),type:'text',...preset};const result=await UI.modal({title:'Campo de captura',html:sfNamed('label','Nombre del campo',f.label||'')+sfNamed('scope','Función',f.scope,'select',[['*','Todas'],...ACTIVITIES.filter(x=>x[0]!=='documentos').map(x=>[x[0],x[2]]),['permiso','Permisos']])+sfNamed('type','Tipo de dato',f.type,'select',[['text','Texto'],['textarea','Texto largo'],['number','Número'],['date','Fecha'],['select','Listado']])+sfNamed('options','Opciones del listado — una por línea',(f.options||[]).join('\n'),'textarea')+sfNamed('required','Obligatorio al finalizar',f.required?'Sí':'No','select',['No','Sí'])+'<p>Los valores anteriores se conservan. Los campos adicionales se almacenan en el registro y en Detalle_Campos de Sheets; la ubicación impresa se gestiona en el formato controlado.</p>',buttons:[{label:'Cancelar',value:false},{label:'Guardar campo',value:true,cls:'pri',validate:v=>{if(!v.label.trim())throw Error('Indique el nombre.');if(v.type==='select'&&!v.options.trim())throw Error('Indique las opciones.');}}]});if(!result.value)return;const v=result.form,next={...f,label:v.label.trim(),scope:v.scope,type:v.type,options:v.options.split('\n').map(x=>x.trim()).filter(Boolean),required:v.required==='Sí',active:true};const fields=this.fields.filter(x=>x.id!==f.id).concat(next);await this.persist(fields);render();},
 async persist(fields){if(Cloud.user){if(Cloud.user.role!=='admin')throw Error('Requiere Administrador.');await Cloud.api('config',{write:true,values:{captureSchema:fields}});}this.fields=fields;await Store.put('meta',{k:'capture-schema',value:fields});},
 async manage(){requireAdmin();await UI.modal({title:'Campos y tipos de datos',html:'<p>Configure campos adicionales para todas las funciones o una función específica. En una ficha abierta, “Configurar campos de esta pantalla” permite adaptar los campos existentes.</p>'+vb('Editar campos existentes','schema-existing41')+vb('Agregar campo','schema-add')+this.fields.map(f=>'<div class="v3-row"><span>'+esc(f.label+' · '+f.scope+' · '+f.type+(f.active===false?' · Inactivo':''))+'</span><div>'+vb('Editar','schema-edit','data-id="'+f.id+'"')+vb(f.active===false?'Activar':'Desactivar','schema-toggle','data-id="'+f.id+'"')+'</div></div>').join('')});},
 async screen(){requireAdmin();const nodes=[...document.querySelectorAll('#view [data-v3-field],#view [data-bind^="datos."],#view [data-sf-field]')].filter(el=>!['project','system','date','code','datos.proyecto','datos.fecha'].includes(el.dataset.v3Field||el.dataset.bind||el.dataset.sfField));if(!nodes.length){await this.edit();return;}const entries=nodes.map(el=>{const binding=el.dataset.v3Field||el.dataset.bind||el.dataset.sfField;return {binding,label:el.closest('label')?.querySelector('span')?.textContent||binding,type:el.tagName==='SELECT'?'select':el.tagName==='TEXTAREA'?'textarea':['number','date'].includes(el.type)?el.type:'text',options:el.tagName==='SELECT'?[...el.options].map(o=>o.value).filter(Boolean):[]};});const a=await UI.modal({title:'Seleccionar campo de esta pantalla',html:sfNamed('binding','Campo',entries[0].binding,'select',entries.map(x=>[x.binding,x.label])),buttons:[{label:'Cancelar',value:false},{label:'Configurar',value:true,cls:'pri'}]});if(a.value){const f=entries.find(x=>x.binding===a.form.binding),old=this.fields.find(x=>x.binding===f.binding&&x.scope===this.scope());await this.edit(old?.id,{...f,scope:this.scope()});}},
 errors(r){return this.applicable(r).flatMap(f=>{const v=this.value(r,f);if(v===undefined||v===null||v==='')return f.required?[f.label+': obligatorio.']:[];if(f.type==='number'&&!Number.isFinite(Number(v)))return [f.label+': debe ser un número.'];if(f.type==='select'&&!f.options.includes(String(v)))return [f.label+': seleccione una opción vigente.'];if(f.type==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(String(v)))return [f.label+': fecha inválida.'];return [];});},
 mount(){const r=this.current();if(!r||!Portal.role||!(App.view==='ficha'||App.view==='portal'&&['form','rayado','permiso','rca','nc-edit'].includes(Portal.page)))return;const disabled=r._readOnly||(r.uuid?r.estado:r.state)!=='Borrador';for(const f of this.applicable(r).filter(x=>x.binding)){const el=[...document.querySelectorAll('#view [data-v3-field],#view [data-bind],#view [data-sf-field]')].find(el=>(el.dataset.v3Field||el.dataset.bind||el.dataset.sfField)===f.binding);if(!el)continue;const wrap=document.createElement('div');wrap.innerHTML=this.input(f,this.value(r,f));const input=wrap.firstElementChild;for(const a of [...el.attributes])if(a.name.startsWith('data-')||['id','class','disabled'].includes(a.name))input.setAttribute(a.name,a.value);input.dataset.schemaId=f.id;input.required=!!f.required;const label=el.closest('label')?.querySelector('span');if(label)label.textContent=f.label+(f.required?' *':'');el.replaceWith(input);}
 const extra=this.applicable(r).filter(x=>!x.binding),box=document.createElement('section');box.className='card';box.id='schema-extra';box.innerHTML='<h3>Datos adicionales</h3><fieldset '+(disabled?'disabled':'')+'><div class="grid2">'+extra.map(f=>'<label class="fld"><span>'+esc(f.label)+(f.required?' *':'')+'</span>'+this.input(f,this.value(r,f)).replace(/^<(input|select|textarea)/,'<$1 data-custom="'+f.id+'"')+'</label>').join('')+'</div></fieldset>'+(Portal.role==='admin'?vb('Configurar campos de esta pantalla','schema-screen')+vb('Agregar campo','schema-add'):'');if(extra.length||Portal.role==='admin')(document.querySelector('.workspace-content')||document.querySelector('#view')).append(box);
 }
};
const schemaCatalog=Cloud.catalog.bind(Cloud);Cloud.catalog=async function(write){await schemaCatalog(write);if(!write){const data=await this.api('config');Schema.fields=data.captureSchema||[];await Store.put('meta',{k:'capture-schema',value:Schema.fields});render();}};
const schemaErrors=FormEditor.errors.bind(FormEditor);FormEditor.errors=(r,final)=>[...schemaErrors(r,final),...Schema.errors(r)];
const inspectionErrors=Insp.finalizeErrors.bind(Insp);Insp.finalizeErrors=i=>[...inspectionErrors(i),...Schema.errors(i)];
const updatedAction=V3Events.action.bind(V3Events);V3Events.action=async function(b,e){const a=b.dataset.v3;if(['record-final','simple-final','nc-word','rca-xlsx','record-pdf','simple-pdf'].includes(a)&&Portal.record){const errors=Schema.errors(Portal.record);if(errors.length)throw Error(errors.join('\n'));}switch(a){case'functions':await Portal.flush();Portal.record=null;Portal.page='functions';App.view='portal';render();return;case'draft-delete':return deleteDraft(b.dataset.id,b.dataset.legacy==='true');case'legacy-open':return openInsp(b.dataset.id);case'dashboard-refresh':await Dash.load();if(Cloud.user)await Cloud.refresh();render();return;case'dashboard-clear':Dash.filters={};render();return;case'dashboard-group':Dash.filters[b.dataset.key]=b.dataset.value;render();return;case'doc-search':DocLinks.query=$('#doc-query').value;DocLinks.project=$('#doc-project').value;render();return;case'doc-clear':DocLinks.query='';DocLinks.project='';DocLinks.category='Todos';DocLinks.contractor='';render();return;case'schema-admin':return Schema.manage();case'schema-add':return Schema.edit();case'schema-screen':return Schema.screen();case'schema-edit':return Schema.edit(b.dataset.id);case'schema-toggle':requireAdmin();await Schema.persist(Schema.fields.map(f=>f.id===b.dataset.id?{...f,active:f.active===false}:f));UI.toast('Campo actualizado.');render();return;default:return updatedAction(b,e);}};
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.dashboard){Dash.filters[el.dataset.dashboard]=el.value;render();}if(el.id==='doc-project'){DocLinks.query=$('#doc-query').value;DocLinks.project=el.value;render();}},true);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='doc-query'){DocLinks.query=e.target.value;render();}});
document.addEventListener('input',e=>{const el=e.target,r=Schema.current(),id=el.dataset.custom||el.dataset.schemaId;if(!id||!r||r._readOnly)return;const f=Schema.fields.find(f=>f.id===id);if(!f)return;const value=f.type==='number'&&el.value!==''?Number(el.value):el.value;if(el.dataset.custom){r.customData??={};r.customData[id]=value;}else if(f.binding.startsWith('datos.'))r.datos[f.binding.slice(6)]=value;else r[f.binding]=value;if(r.uuid){saveNow().catch(err=>UI.toast(errMsg(err),'err'));}else Portal.changed();},true);
const updateRender=render;render=function(){updateRender();Schema.mount();const brand=document.querySelector('.brand');if(brand&&!brand.querySelector('.new-app-icon')){const img=document.createElement('img');img.className='new-app-icon';img.src=APP_ICON;img.alt='SOF-CAL';brand.querySelector('svg')?.remove();brand.prepend(img);}if(App.view==='ficha'&&App.insp?.estado==='Borrador'&&!ro())document.querySelector('#view')?.insertAdjacentHTML('beforeend',vb('Eliminar este borrador','draft-delete','data-id="'+App.insp.uuid+'" data-legacy="true"','danger-o'));};
const editOriginalField=FormEditor.editField.bind(FormEditor);FormEditor.editField=async function(id){if(this.locked())return;const r=Portal.record,binding='fields.'+id,f=Schema.fields.find(x=>x.binding===binding&&(x.scope===r.kind||x.scope==='*'));if(!f&&Portal.role!=='admin')return editOriginalField(id);const t=this.template().fields.flat().find(x=>x.id===id);const def=f||{label:t?.label||'Casilla del formato',type:'textarea',options:[]};const response=await UI.modal({title:def.label,html:'<label class="fld"><span>'+esc(def.label)+'</span>'+Schema.input(def,r.fields[id]).replace(/^<(input|textarea|select)/,'<$1 name="value"')+'</label>'+(Portal.role==='admin'?'<p>Puede configurar el tipo de captura de esta casilla sin modificar su posición impresa.</p>':''),buttons:[{label:'Cancelar',value:false},...(Portal.role==='admin'?[{label:'Configurar tipo',value:'config'}]:[]),{label:'Guardar',value:true,cls:'pri'}]});if(response.value==='config')return Schema.edit(f?.id,{binding,scope:r.kind,label:def.label,type:def.type});if(response.value){r.fields[id]=response.form.value;Portal.changed();await Portal.save();this.overlay();}};
const schemaValueOriginal=Schema.value.bind(Schema);Schema.value=function(r,f){return f.binding?.startsWith('fields.')?r.fields?.[f.binding.slice(7)]:schemaValueOriginal(r,f);};

const refreshDashboard=Cloud.refresh.bind(Cloud);Cloud.refresh=async function(){await refreshDashboard();await Dash.load();if(Portal.page==='home'&&App.view==='portal')render();};
